function UIEntrustQueueNode:Refresh(data, clickCb, status, ind, curLevelId)
    if not data then
        return
    end
    --先清空一下倒计时
    self:ClearTimeDown()

    self._data = data
    self._status = status
    self._clickCb = clickCb
    self._vo = CfUtils.GetCfVo(AutoIds.IdSetting610, "EntrustBattleTeamUnlockVo", self._data.id)
    self._curInd = checkNumber(ind)
    self._curLevelId = checkNumber(curLevelId)

    self:FillEntrustQueue()
    self:RefreshSelect(false)
    KTool.SetActive(self.Root, true)
    KTool.SetActive(self.btns, true)
end

function UIEntrustQueueNode:FillEntrustQueue()
    local isUnlock = (checkNumber(self._data.unlock) == 1)
    KTool.SetActive(self.lock, not isUnlock)
    KTool.SetActive(self.unLock, isUnlock)

    CfUtils.FillText(self.lockEntrustId, self._data.id)
    CfUtils.FillText(self.unLockEntrustId, self._data.id)
    --CfUtils.FillImage(self.lockEntrustId, "uiatlas/FightTeam/EntrustTeam/auto_jpg_0"..self._data.id..".png")
    --CfUtils.FillImage(self.unLockEntrustId, "uiatlas/FightTeam/EntrustTeam/auto_jpg_0"..self._data.id..".png")

    local isHaveTask = teamComponent:IsEntrustQueuesBusy(self._data.id)
    local isFinish = teamComponent:IsEntrustingEnd(self._data.id)

    --如果已解锁
    if isUnlock then
        CfUtils.FillText(self.TxtArmed, localize("武装值"))
        CfUtils.FillText(self.ArmedNum, teamComponent:GetTeamFightingPower(self._data.cardsId))
        --KTool.SetActive(self.FontStyleButton, (self._status == STATUS.ALL) and isHaveTask)
        --KTool.SetActive(self.cancel, (self._status == STATUS.ALL) and isHaveTask and not isFinish)
        --KTool.SetActive(self.btnFree, not isHaveTask)
        --KTool.SetActive(self.ImgStateIcon, (self._status == STATUS.TEAMSELECT) and isHaveTask)
        --如果有任务再执行
        KTool.SetActive(self.cancel, isHaveTask and (not isFinish) )
        KTool.SetActive(self.ImgStateIcon, isHaveTask and isFinish)
        if isHaveTask then
            --获取关卡配置
            local questData = QuestConfMgr:GetInstance():GetQuestVoById(self._data.questId)
            if not questData then
                return
            end
            --CfUtils.FillText(self.questInfo, questData.name)

            --如果已完成
            if isFinish then
                --CfUtils.FillImage(self.Root, 'uiatlas/fightTeam/EntrustTeam/auto_bg_team_finish.png')
                --队列界面的时候才有按钮
                --if self._status == STATUS.ALL then
                    self:RefreshBtnGetReward()
                --else
                --    CfUtils.FillImage(self.ImgStateIcon, "UIAtlas/FightTeam/EntrustTeam/auto_jpg_finish.png")
                --end
            else
                ---有任务未完成，委托中
                --CfUtils.FillImage(self.Root, 'uiatlas/fightTeam/EntrustTeam/auto_bg_team_autoing.png')
                --if self._status == STATUS.ALL then
                    --CfUtils.FillText(self.TxtSession, localize("(当前场次"..teamComponent:GetAllEntrustTime(self._data.id).."/"..self._data.questSum..")"))
                    self:RefreshBtnGetCancel()
                
                    --计时器
                    self._timer = CDTimerModule.GetInstance():AddCD(1, function(count, id)
                        self:RefreshTime()
                    end, 604800, true, true, true)
                --else
                --    CfUtils.FillImage(self.ImgStateIcon, "UIAtlas/FightTeam/EntrustTeam/auto_jpg_autoing.png")
                --end
            end
        else
            ---空闲中
            CfUtils.FillImage(self.Root, 'uiatlas/fightTeam/EntrustTeam/auto_bg_team_free.png')
            --CfUtils.FillText(self.questInfo, "")
            --CfUtils.FillText(self.btnFree.transform:Find("Text"), localize("空闲中"))
        end

        self:FillEntrustTeamMembers()
    else
        ---未解锁的背景图
        CfUtils.FillImage(self.Root, 'uiatlas/fightTeam/EntrustTeam/auto_bg_team_lock.png')
        if self._vo then
            CfUtils.FillText(self.cfText4, GameUtils.GetUnlockDescr(self._vo.unlockType, self._vo.unlockNum))
        end
    end
end

--绘制有任务时的队员状态
function UIEntrustQueueNode:FillEntrustTeamMembers()
    local memberData = self._data.cardsId
    if not memberData or table.count(memberData) == 0 then
        memberData = {}
        for i = 1, 4 do
            table.insert(memberData, {})
        end
    end
    for i = 1, self._maxTeamnum do
        local go = self.teamInfo.transform:Find("card"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.card, self.teamInfo)
            go.name = "card"..i
        end
        local scr = CfUtils.GetLuaScr(go, UIEntrustQueueCardNode)
        KTool.SetActive(go, true)
        if scr then
            scr:Refresh(memberData[i], self._data.id, self._status, self._curLevelId)
        end
    end
end

