        --CfUtils.FillText(self.time, 0)
        --CfUtils.FillText(self.TxtSession, localize("(当前场次"..self._data.questSum.."/"..self._data.questSum..")"))

        --小于0  显示领取
        self:RefreshBtnGetReward()
