function UIEntrustQueueNode:PlayAni()
    local canvasGroup = self.Root.transform:GetComponent(typeof(CanvasGroup))
    canvasGroup.alpha = 0
    local localPosition = self.Root.transform.localPosition
    self.Root.transform.localPosition = Vector3.New(localPosition.x, localPosition.y - 45, localPosition.z)
    local sequence = DOTween:Sequence()
    local moveAni = self.Root.transform:DOLocalMoveY(localPosition.y, 0.3):SetDelay(0.03 * self._curInd)
    local fadeAni = canvasGroup:DOFade(1, 0.3):SetDelay(0.03 * self._curInd)
    sequence:Append(moveAni)
    sequence:Join(fadeAni)
end

function UIEntrustQueueNode:OnSelect()
    --只有在队伍选人的时候可以点
    if self._status == STATUS.ALL then
        return
    end
    local isUnlock = (checkNumber(self._data.unlock) == 1)
    --如果未解锁
    if not isUnlock then
        if checkNumber(self._vo.unlockType) == Constants.CommonUnlockType.Gold or 
         checkNumber(self._vo.unlockType) == Constants.CommonUnlockType.Diamond then
            local col = (GoodsUtils.GetThingNo(self._vo.unlockId) >= checkNumber(self._vo.unlockNum)) and nil or "#ff0000"
            GameUtils.SecondConfirm(localize("确认要花费_num__name_购买改队列吗", {_num_ = string.format_color_tag(self._vo.unlockNum, col), _name_ = GoodsConfMgr:GetInstance():GetGoodsVoById(self._vo.unlockId).name}), function()
                teamComponent:BuyEntrustRequeueReq(self._data.id)        
            end)
        end
        return
    end

    if self._clickCb then
        self._clickCb()
    end
end

function UIEntrustQueueNode:ClearTimeDown()
    if not isNull(self._timer) then
        CDTimerModule.GetInstance():RemoveCD(self._timer)
    end
end

function UIEntrustQueueNode:OnDestroy()
    self:ClearTimeDown()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIEntrustQueueNode
